def safe_json_path_lookup(data: dict | list, path: str, default: any = None) -> any:
    if not path:
        return data
    keys = path.split('.')
    for key in keys:
        if key.isdigit():
            key = int(key)
        if isinstance(data, dict) and key in data:
            data = data[key]
        elif isinstance(data, list) and 0 <= key < len(data):
            data = data[key]
        else:
            return default
