def compact_number_formatter(n: int | float) -> str:
    if n == 0:
        return "0"
    if n < 0:
        return "-" + compact_number_formatter(-n)

    suffixes = ['K', 'M', 'B']
    for suffix in suffixes:
        if abs(n) < 1000:
            break
        n /= 1000

    if n.is_integer():
        return str(int(n)) + suffix
    else:
        return f"{n:.1f}".rstrip('0').rstrip('.') + suffix

