def time_diff_humanized(seconds: int) -> str:
    if seconds == 0:
        return '0s'

    units = []
    if seconds >= 86400:
        days = seconds // 86400
        units.append(f'{days}d')
        seconds %= 86400
    if seconds >= 3600:
        hours = seconds // 3600
        units.append(f'{hours}h')
        seconds %= 3600
    if seconds >= 60:
        minutes = seconds // 60
        units.append(f'{minutes}m')
        seconds %= 60
    if seconds > 0:
        units.append(f'{seconds}s')

    return ' '.join(units)

def find_first_missing_positive(nums: list[int]) -> int:
    n = len(nums)
    if 1 not in nums:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1s
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 1

    # Use index as a hash key and number sign as a presence detector
    for i in range(n):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # The first positive index+1 is the missing number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all numbers are present
    return n + 1

def calculate_tax_bracket(income: float, brackets: list[tuple[float, float]]) -> float:
    if income <= 0:
        return 0.0

    tax = 0.0
    for upper_limit, rate in brackets:
        if income <= upper_limit:
            tax += (income - (income if income < upper_limit else 0)) * rate
            break
        tax += (upper_limit - (income if income < upper_limit else 0)) * rate
        income -= upper_limit

    return round(tax, 2)

