def simple_caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if char.isalpha():
            base = 'A' if char.isupper() else 'a'
            offset = (ord(char) - ord(base) + shift) % 26
            result.append(chr(ord(base) + offset))
        else:
            result.append(char)
    return ''.join(result)

