def run_length_compress(data: list[int]) -> list[tuple[int, int]]:
    if not data:
        return []

    compressed = []
    current_value = data[0]
    count = 1

    for value in data[1:]:
        if value == current_value:
            count += 1
        else:
            compressed.append((current_value, count))
            current_value = value
            count = 1

    compressed.append((current_value, count))
    return compressed

